/**
 * `withEnv(overrides, fn)` helper for AIClient tests that need to mutate
 * `process.env` (selector / singleton / provider-config tests).
 *
 * Behaviour:
 *   1. Snapshot the previous values of every key in `overrides`.
 *   2. Apply the overrides (`undefined` deletes the key).
 *   3. Reset the lazy AIClient singleton (`resetAIClient()`) so the next
 *      `getAIClient()` re-reads env.
 *   4. Run `fn`, then restore every previous env value and reset the
 *      singleton again — even if `fn` throws.
 *
 * Used by:
 *   - Phase 2 mock-provider snapshot test (deterministic seed env)
 *   - Phase 5 env-matrix selector tests (the original consumer per
 *     `test-strategy.md` §2)
 *   - Phase 6/7 service-class regression tests
 *
 * Failure mode this helper prevents: order-dependent flakes when one test
 * leaks `AI_PROVIDER`, `OPENAI_API_KEY`, etc. into the next test.
 */
import { resetAIClient } from "../client.js";

/**
 * Map of environment-variable names to override values. A value of
 * `undefined` *deletes* the variable for the duration of the callback.
 */
export type EnvOverrides = Record<string, string | undefined>;

/**
 * Run `fn` with `process.env` patched by `overrides`. Restores the
 * previous values (and resets the AIClient singleton) on exit.
 *
 * @param overrides - Env var name → new value (`undefined` deletes the var).
 * @param fn - Async callback executed with the patched env.
 * @returns Whatever `fn` returns.
 */
export async function withEnv<T>(
  overrides: EnvOverrides,
  fn: () => Promise<T> | T
): Promise<T> {
  const previous: EnvOverrides = {};

  for (const [key, value] of Object.entries(overrides)) {
    previous[key] = process.env[key];
    if (value === undefined) {
      delete process.env[key];
    } else {
      process.env[key] = value;
    }
  }

  resetAIClient();

  try {
    return await fn();
  } finally {
    for (const [key, value] of Object.entries(previous)) {
      if (value === undefined) {
        delete process.env[key];
      } else {
        process.env[key] = value;
      }
    }
    resetAIClient();
  }
}

/**
 * Shared AIClient contract harness.
 *
 * Re-runs the Phase 2 mock-provider assertions against any concrete
 * `AIClient` implementation. Phases 3 (OpenAI) and 4 (Google) inherit
 * this suite by calling `runAIClientContract(() => makeProvider())`
 * inside their own `*.test.ts` files; that way every new provider must
 * satisfy the same observable contract or the contract suite goes red.
 *
 * Design notes:
 *   - The factory takes a `responses` arg so OpenAI/Google can stub their
 *     SDK mocks with the same fixture before `makeClient` is invoked.
 *   - `prompt: 'phase-2-contract'` is a sentinel string that providers
 *     can pattern-match in their SDK mocks to return the fixture.
 *   - The suite asserts *behaviour*, not internals (no spies on private
 *     state) — so adding a new provider does not require touching the
 *     contract.
 */
import { describe, expect, it } from "vitest";
import type { AIClient } from "../types.js";
import {
  recommendationFixture,
  recommendationFixturePrompt,
  recommendationFixtureSchema,
} from "./recommendations.js";
import { diagramBuffer } from "./diagram.js";

/**
 * Optional pre-configured responses that providers may need to wire into
 * their underlying SDK mocks before `makeClient()` is invoked.
 */
export interface ContractFixtures {
  /** Object the provider should return for the recommendation prompt. */
  recommendationObject: typeof recommendationFixture;
  /** Image bytes the provider should return for `generateImage`. */
  imageBuffer: Buffer;
  /** Text the provider should return for `generateText`. */
  textOutput: string;
}

/**
 * Default fixture set used by `runAIClientContract`. Providers that need
 * to wire their SDK mocks can read these values and configure their stubs
 * before calling `runAIClientContract`.
 */
export const defaultContractFixtures: ContractFixtures = {
  recommendationObject: recommendationFixture,
  imageBuffer: diagramBuffer,
  textOutput: "phase-2 contract text output",
};

/**
 * Factory that returns a fresh `AIClient` per test. The factory receives
 * the fixture set so it can wire its SDK mocks to return matching values.
 */
export type AIClientFactory = (fixtures: ContractFixtures) => AIClient;

/**
 * Run the standard AIClient contract suite against the client returned
 * by `makeClient`. Intended to be called from inside an existing
 * `describe()` block so each provider's contract pass is visible in its
 * own test output.
 *
 * @param providerName - Display name for the `describe` block.
 * @param makeClient - Factory producing the client under test, given the
 *   fixture set so the implementer can stub their SDK mocks.
 * @param fixtures - Override fixture set; defaults to `defaultContractFixtures`.
 */
export function runAIClientContract(
  providerName: string,
  makeClient: AIClientFactory,
  fixtures: ContractFixtures = defaultContractFixtures
): void {
  describe(`AIClient contract — ${providerName}`, () => {
    it("generateObject returns the schema-validated response", async () => {
      const client = makeClient(fixtures);

      const result = await client.generateObject({
        schema: recommendationFixtureSchema,
        prompt: recommendationFixturePrompt,
      });

      expect(result).toEqual(fixtures.recommendationObject);
    });

    it("generateObject result satisfies the Zod schema", async () => {
      const client = makeClient(fixtures);

      const result = await client.generateObject({
        schema: recommendationFixtureSchema,
        prompt: recommendationFixturePrompt,
      });

      expect(recommendationFixtureSchema.safeParse(result).success).toBe(true);
    });

    it("generateImage returns a Buffer (not a Uint8Array)", async () => {
      const client = makeClient(fixtures);

      const result = await client.generateImage({
        prompt: "phase-2-contract image",
      });

      expect(Buffer.isBuffer(result)).toBe(true);
      expect(result.equals(fixtures.imageBuffer)).toBe(true);
    });

    it("generateText returns the configured string", async () => {
      const client = makeClient(fixtures);

      const result = await client.generateText({
        prompt: "phase-2-contract text",
      });

      expect(typeof result).toBe("string");
      expect(result).toBe(fixtures.textOutput);
    });
  });
}

/**
 * Phase 2 Red-phase tests for the mock AI provider.
 *
 * Driven by `measure/tracks/ai_adapter_package_20260603/plan.md` Phase 2
 * task 5 ("Add snapshot test: feed a prompt, capture the response, snapshot
 * for regression") and `test-strategy.md` §2 ("Add an exported
 * `createTestClient(overrides)` helper that returns a `MockAIClient`
 * pre-loaded with the fixtures").
 *
 * What this file pins:
 *   1. `createTestClient` is exported from `../providers/mock.js` and from
 *      the public barrel `../index.js` so Phase 6/7 service-class tests
 *      can pull a pre-loaded `AIClient` in one line.
 *   2. `createTestClient()` returns a working `MockProvider` whose
 *      `generateObject`/`generateImage`/`generateText` calls succeed with
 *      the standard fixture set (no extra wiring required).
 *   3. Per-call overrides (`createTestClient({ generateText: 'custom' })`)
 *      win over the fixture defaults.
 *   4. The shared `runAIClientContract` harness is exercised against the
 *      mock — this is the contract Phases 3 and 4 inherit.
 *   5. A snapshot of the mock's recommendation response is stored under
 *      `__snapshots__/`, so any future drift in either the fixture or
 *      MockProvider's pass-through path goes red on the next test run.
 *
 * RED expectations on first run (pre-implementation):
 *   - `createTestClient` is not exported by `../providers/mock.ts`. Items
 *     1-5 above all fail with `TypeError: createTestClient is not a function`
 *     (or a structurally equivalent import error).
 *   - The Green-phase implementer must add `createTestClient` to
 *     `src/providers/mock.ts` and re-export it from `src/index.ts`.
 *     No other source change is required for Phase 2 to go green.
 */
import { describe, expect, it } from "vitest";
import { z } from "zod";

import { MockProvider } from "../providers/mock.js";
// `createTestClient` is *expected* to exist after Phase 2 Green; the import
// is intentionally optimistic so the Red phase fails noisily.
import { createTestClient } from "../providers/mock.js";
import * as barrel from "../index.js";

import {
  recommendationFixture,
  recommendationFixturePrompt,
  recommendationFixtureSchema,
} from "../__fixtures__/recommendations.js";
import { diagramBuffer } from "../__fixtures__/diagram.js";
import {
  defaultContractFixtures,
  runAIClientContract,
} from "../__fixtures__/contract-suite.js";

describe("Phase 2 — createTestClient helper (test-strategy.md §2)", () => {
  it("is exported from providers/mock.js", () => {
    expect(createTestClient).toBeDefined();
    expect(typeof createTestClient).toBe("function");
  });

  it("is re-exported from the public barrel (packages/ai)", () => {
    expect(
      (barrel as Record<string, unknown>).createTestClient
    ).toBeDefined();
    expect(
      typeof (barrel as Record<string, unknown>).createTestClient
    ).toBe("function");
  });

  it("returns a MockProvider preloaded with all standard fixtures", async () => {
    const client = createTestClient();

    expect(client).toBeInstanceOf(MockProvider);

    const obj = await client.generateObject({
      schema: recommendationFixtureSchema,
      prompt: recommendationFixturePrompt,
    });
    expect(obj).toEqual(recommendationFixture);

    const img = await client.generateImage({ prompt: "any" });
    expect(Buffer.isBuffer(img)).toBe(true);
    expect(img.equals(diagramBuffer)).toBe(true);

    const txt = await client.generateText({ prompt: "any" });
    expect(typeof txt).toBe("string");
    expect(txt).toBe(defaultContractFixtures.textOutput);
  });

  it("per-call overrides win over fixture defaults", async () => {
    const customSchema = z.object({ ok: z.boolean() });
    const client = createTestClient({
      generateObject: { ok: true },
      generateText: "overridden",
    });

    await expect(
      client.generateObject({ schema: customSchema, prompt: "x" })
    ).resolves.toEqual({ ok: true });

    await expect(client.generateText({ prompt: "x" })).resolves.toBe(
      "overridden"
    );

    // generateImage was *not* overridden — falls back to the fixture default.
    const img = await client.generateImage({ prompt: "y" });
    expect(img.equals(diagramBuffer)).toBe(true);
  });
});

// -----------------------------------------------------------------------
// Shared contract suite — Phases 3 and 4 will call `runAIClientContract`
// with their own factories. Phase 2 establishes the baseline by running
// it against the mock so the harness itself is exercised in CI.
// -----------------------------------------------------------------------

runAIClientContract("MockProvider via createTestClient", () =>
  createTestClient()
);

// -----------------------------------------------------------------------
// Snapshot test — plan.md Phase 2 task 5.
// -----------------------------------------------------------------------

describe("Phase 2 — mock provider snapshot (plan.md §Phase 2 task 5)", () => {
  it("emits the captured recommendation fixture for the deterministic prompt", async () => {
    const client = createTestClient();

    const result = await client.generateObject({
      schema: recommendationFixtureSchema,
      prompt: recommendationFixturePrompt,
    });

    expect(result).toMatchSnapshot();
  });

  it("emits the 1×1 PNG buffer for the deterministic image prompt", async () => {
    const client = createTestClient();

    const buf = await client.generateImage({
      prompt: "phase-2 deterministic diagram prompt",
    });

    expect({
      isBuffer: Buffer.isBuffer(buf),
      byteLength: buf.byteLength,
      base64: buf.toString("base64"),
    }).toMatchSnapshot();
  });
});

